<?php
function heading(string $eyebrow,string $title,string $description=''):void{echo '<div class="page-heading"><div><p class="eyebrow">'.h($eyebrow).'</p><h1>'.h($title).'</h1><p class="muted">'.h($description).'</p></div></div>';}
function cover(string $key):void{$symbols=['web'=>'</>','programming'=>'{ }','database'=>'▤','default'=>'SM'];echo '<div class="cover '.h($key).'"><span class="cover-grid"></span><span class="cover-symbol">'.h($symbols[$key]??'SM').'</span><span class="cover-label">STUDYMATE / LEARN</span></div>';}
function statusName(string $s):string{return ['draft'=>'Bản nháp','published'=>'Đã xuất bản','archived'=>'Đã lưu trữ'][$s]??$s;}
function statusBadge(string $s):string{return '<span class="status '.h($s).'">'.h(statusName($s)).'</span>';}
function progressBar(array $p):void{echo '<div class="progress-meta"><span>Tiến độ bài học</span><strong>'.h($p['percent']).'%</strong></div><div class="progress" role="progressbar" aria-valuenow="'.h($p['percent']).'" aria-valuemin="0" aria-valuemax="100"><div class="progress-bar" style="width:'.h($p['percent']).'%"></div></div>';}
function statCard(string $label,$value,string $sub=''):void{echo '<div class="stat"><span>'.h($label).'</span><strong>'.h($value).'</strong><small>'.h($sub).'</small></div>';}
function emptyState(string $title,string $detail=''):void{echo '<div class="empty"><span class="empty-icon">□</span><h3>'.h($title).'</h3><p>'.h($detail).'</p></div>';}
function courseCard(array $c,?array $e=null):void{echo '<article class="course-card"><a href="'.h(url($e?'learn':'detail',['id'=>$c['id']])).'">';cover($c['cover_key']);echo '<div class="card-content"><p class="eyebrow">'.h($c['category_name']).'</p><h3>'.h($c['title']).'</h3><p class="muted clamp">'.h($c['description']).'</p>';if($e){$p=isset($e['total'])?rowProgress($e):progressFor((int)$e['user_id'],(int)$c['id']);progressBar($p);echo '<p class="small mt-3">'.($e['completed_at']?'Đã hoàn thành khóa học':($p['percent']==100?'Đã học đủ bài · tiếp tục quiz':'Đang học')).($p['best']!==null?' · Điểm tốt nhất '.h($p['best']).'%':'').'</p>';}else echo '<div class="card-meta"><span>'.h($c['instructor_name']).'</span><strong>Miễn phí</strong></div>';echo '</div></a></article>';}
function field(string $name,string $label,string $value='',string $type='text',string $attrs=''):void{static $counter=0;$fieldId=$name.'-'.(++$counter);echo '<label for="'.h($fieldId).'">'.h($label).'<input class="form-control" id="'.h($fieldId).'" name="'.h($name).'" type="'.h($type).'" value="'.h($value).'" '.$attrs.'></label>';}
function area(string $name,string $label,string $value='',string $attrs=''):void{echo '<label>'.h($label).'<textarea class="form-control" name="'.h($name).'" '.$attrs.'>'.h($value).'</textarea></label>';}
function markdown(string $body):string{$out='';$code=false;$buf='';foreach(explode("\n",str_replace("\r",'',$body)) as $line){if(str_starts_with($line,'```')){if($code){$out.='<pre><code>'.h($buf).'</code></pre>';$buf='';}$code=!$code;continue;}if($code){$buf.=$line."\n";continue;}if(preg_match('/^(#{1,3})\s+(.+)$/',$line,$m)){$n=strlen($m[1]);$out.="<h$n>".h($m[2])."</h$n>";}elseif(trim($line)!=='')$out.='<p>'.h($line).'</p>'; }if($code)$out.='<pre><code>'.h($buf).'</code></pre>';return $out;}
function lessonViewer(array $l):void{echo '<article class="lesson-text">'.markdown($l['body']);if($l['youtube_video_id'])echo '<iframe title="Video bài học" src="https://www.youtube-nocookie.com/embed/'.h($l['youtube_video_id']).'" allowfullscreen></iframe>';echo '</article>';}
function pageHome():void{
?><section class="hero container"><div><p class="eyebrow">KHỞI ĐẦU NHỎ · TIẾN BỘ MỖI NGÀY</p><h1>Học từng bước.<br><span>Hiểu từng bài.</span></h1><p class="hero-description">Một nơi để học kiến thức mới, theo dõi tiến độ và luyện tập. StudyMate đồng hành cùng bạn từ bài học đầu tiên.</p><div class="flex gap"><a class="btn btn-primary btn-lg" href="<?=h(url('courses'))?>">Khám phá khóa học ↗</a><a class="btn btn-outline-secondary btn-lg" href="<?=h(url('register'))?>">Tạo tài khoản miễn phí</a></div><div class="hero-points"><span>✓ Học theo nhịp của bạn</span><span>✓ Quiz cuối khóa</span><span>✓ Trợ lý theo bài học</span></div></div><div class="hero-art"><div class="art-orbit"></div><div class="art-card"><span class="eyebrow">LỘ TRÌNH CỦA BẠN</span><h3>Hôm nay, học một điều mới.</h3><?php foreach(['Khám phá kiến thức','Kiểm tra hiểu biết','Theo dõi tiến bộ'] as $i=>$title):?><div class="art-lesson"><span class="art-num">0<?=$i+1?></span><div><strong><?=h($title)?></strong><small>Học tập theo nhịp độ riêng</small></div><span>↗</span></div><?php endforeach?><div class="art-bottom">Một hành trình. Nhiều bước tiến.</div></div><div class="floating-label">✦ Học có định hướng</div></div></section><section class="container"><?php heading('BẮT ĐẦU TẠI ĐÂY','Khóa học dành cho bạn','Nội dung nền tảng, ví dụ dễ hiểu và bài luyện tập cuối khóa.');?><div class="course-grid"><?php foreach(all("SELECT c.*,g.name category_name,u.name instructor_name FROM courses c JOIN categories g ON g.id=c.category_id JOIN users u ON u.id=c.instructor_id WHERE c.status='published' ORDER BY c.created_at DESC,c.id DESC LIMIT 3") as $c)courseCard($c);?></div></section><?php
}
function pageCourses():void{$q=trim(substr((string)($_GET['q']??''),0,100));$cat=(int)($_GET['category']??0);$page=max(1,(int)($_GET['p']??1));$where="c.status='published'";$params=[];if($q!==''){$where.=" AND LOWER(c.title) LIKE LOWER(?) ESCAPE '!'";$params[]='%'.str_replace(['!','%','_'],['!!','!%','!_'],$q).'%';}if($cat){$where.=' AND c.category_id=?';$params[]=$cat;}$count=(int)val('SELECT COUNT(*) FROM courses c WHERE '.$where,$params);$last=max(1,(int)ceil($count/12));$page=min($page,$last);$rows=all('SELECT c.*,g.name category_name,u.name instructor_name FROM courses c JOIN categories g ON g.id=c.category_id JOIN users u ON u.id=c.instructor_id WHERE '.$where.' ORDER BY c.created_at DESC,c.id DESC LIMIT 12 OFFSET '.(($page-1)*12),$params);
?><main class="container"><?php heading('THƯ VIỆN HỌC TẬP','Khám phá khóa học','Chọn một khóa học và bắt đầu hành trình của bạn.');?><form class="filter-bar" method="get" action="/index.php"><?=hidden('page','courses')?><label class="search-field">Tìm theo tên khóa học<input class="form-control" name="q" placeholder="Ví dụ: JavaScript…" value="<?=h($q)?>" maxlength="100"></label><label>Danh mục<select class="form-select" name="category"><option value="">Tất cả danh mục</option><?php foreach(all('SELECT * FROM categories ORDER BY name') as $c):?><option value="<?=$c['id']?>" <?=$cat===$c['id']?'selected':''?>><?=h($c['name'])?></option><?php endforeach?></select></label><button class="btn btn-primary" type="submit">Tìm khóa học</button></form><p class="muted"><?=$count?> khóa học phù hợp</p><div class="course-grid"><?php foreach($rows as $c)courseCard($c);?></div><?php if(!$rows)emptyState('Không tìm thấy khóa học','Thử tên khác hoặc chọn tất cả danh mục.');if($last>1):?><div class="pager"><?php if($page>1):?><a class="btn btn-outline-secondary" href="<?=h(url('courses',['q'=>$q,'category'=>$cat,'p'=>$page-1]))?>">Trước</a><?php endif?><span>Trang <?=$page?> / <?=$last?></span><?php if($page<$last):?><a class="btn btn-outline-secondary" href="<?=h(url('courses',['q'=>$q,'category'=>$cat,'p'=>$page+1]))?>">Sau</a><?php endif?></div><?php endif?></main><?php }
function pageDetail(int $id):void{$c=getCourse($id);if($c['status']!=='published')reject('Khóa học không công khai.',404);$u=currentUser();?><main class="container"><a href="<?=h(url('courses'))?>">← Tất cả khóa học</a><div class="detail-grid"><section><p class="eyebrow mt-4"><?=h($c['category_name'])?></p><h1><?=h($c['title'])?></h1><p class="lead muted"><?=h($c['description'])?></p><p>Biên soạn bởi <strong><?=h($c['instructor_name'])?></strong></p><div class="panel mt-4"><h2>Nội dung khóa học</h2><?php foreach(all('SELECT * FROM chapters WHERE course_id=? ORDER BY position,id',[$id]) as $ch):?><details open><summary><?=h($ch['title'])?></summary><ol><?php foreach(all('SELECT title FROM lessons WHERE chapter_id=? ORDER BY position,id',[$ch['id']]) as $l):?><li><?=h($l['title'])?></li><?php endforeach?></ol></details><?php endforeach?></div><div class="panel mt-3"><h3>Hoàn thành khóa học như thế nào?</h3><p>Đánh dấu tất cả bài học, sau đó đạt ít nhất 70% ở quiz cuối khóa. Bạn được làm lại để luyện tập.</p></div></section><aside class="panel enrollment-panel"><?php cover($c['cover_key']);?><h2 class="mt-4">Miễn phí</h2><p class="muted">Học theo nhịp độ của bạn.</p><?php if(!$u):?><a class="btn btn-primary w-100" href="<?=h(url('login'))?>">Đăng nhập để tham gia</a><?php elseif($u['role']==='student'):echo formStart('enroll',['course_id'=>$id,'return_page'=>'detail']);?><button class="btn btn-primary w-100">Tham gia khóa học</button></form><?php else:?><p class="alert alert-light">Học tập dành cho tài khoản Student.</p><?php endif?><ul class="feature-list"><li>✓ <?=count(courseLessons($id))?> bài học</li><li>✓ Quiz cuối khóa</li><li>✓ Tiến độ được lưu trên server</li></ul></aside></div></main><?php }
function pageAuth(bool $register):void{?><main class="auth-layout container"><section class="auth-story"><p class="eyebrow">STUDYMATE / HỌC MỖI NGÀY</p><h1>Bước tiếp theo<br>bắt đầu từ đây.</h1><p>Đọc bài, luyện tập và xem lại tiến độ. Mỗi bước nhỏ đều giúp bạn tiến xa hơn.</p><?php cover('web');?></section><section class="panel auth-panel"><h2><?=$register?'Tạo tài khoản':'Chào mừng trở lại'?></h2><p class="muted"><?=$register?'Tạo tài khoản Student để bắt đầu học.':'Đăng nhập để tiếp tục hành trình.'?></p><?=formStart($register?'register':'login',['return_page'=>$register?'register':'login'])?><?php if($register)field('name','Họ và tên','', 'text','required minlength="2" maxlength="80" autocomplete="name"');field('email','Email','','email','required maxlength="254" autocomplete="email"');field('password','Mật khẩu','','password','required autocomplete="'.($register?'new-password':'current-password').'"'.($register?' minlength="10"':''));if($register)field('password_confirmation','Xác nhận mật khẩu','','password','required autocomplete="new-password"');?><button class="btn btn-primary w-100"><?=$register?'Tạo tài khoản':'Đăng nhập'?></button></form><p class="mt-3 small"><a href="<?=h(url($register?'login':'register'))?>"><?=$register?'Đã có tài khoản? Đăng nhập':'Chưa có tài khoản? Đăng ký'?></a></p><div class="demo-accounts"><strong>Tài khoản seed để kiểm tra</strong><p>student1@studymate.test<br>instructor1@studymate.test<br>admin@studymate.test</p><p class="small">Mật khẩu được cấu hình trong config.php khi chạy setup. Không dùng tài khoản cá nhân.</p></div></section></main><?php }
function pageStudent():void{
 $u=requireUser('student');$q=trim(substr((string)($_GET['q']??''),0,100));
 $where="e.user_id=? AND c.title LIKE ? ESCAPE '!'";$params=[$u['id'],searchPattern($q)];
 $list=pageQuery('SELECT COUNT(*) FROM enrollments e JOIN courses c ON c.id=e.course_id WHERE '.$where,
 'SELECT c.*,g.name category_name,u.name instructor_name,e.user_id,e.completed_at,COALESCE(totals.total,0) total,COALESCE(done.done,0) done,scores.best FROM enrollments e JOIN courses c ON c.id=e.course_id JOIN categories g ON g.id=c.category_id JOIN users u ON u.id=c.instructor_id '.progressJoins().' WHERE '.$where.' ORDER BY e.created_at DESC,e.id DESC',$params);
 $stats=one('SELECT COUNT(*) total,SUM(CASE WHEN completed_at IS NOT NULL THEN 1 ELSE 0 END) completed FROM enrollments WHERE user_id=?',[$u['id']]);
 ?><main class="container"><?php heading('KHÔNG GIAN HỌC TẬP','Xin chào, '.$u['name'],'Tiếp tục bài đang học hoặc thử một kiến thức mới hôm nay.');?><div class="stats-grid"><?php statCard('Khóa đã tham gia',$stats['total']);statCard('Khóa đã hoàn thành',$stats['completed']??0);statCard('Điều kiện hoàn thành','70%','Học đủ bài và đạt quiz');?></div><h2 class="section-heading">Khóa học của tôi</h2><form class="filter-bar" method="get"><?=hidden('page','student')?><?php field('q','Tìm khóa đã tham gia',$q);?><button class="btn btn-primary">Tìm</button></form><div class="course-grid"><?php foreach($list['rows'] as $e)courseCard($e,$e);?></div><?php if(!$list['rows'])emptyState('Không có khóa học phù hợp','Thử tên khác hoặc tham gia khóa học từ thư viện.');pagination($list);?></main><?php }
function pageLearn(int $id):void{$e=enrolled($id);$c=getCourse($id);$u=requireUser('student');$ls=courseLessons($id);$done=array_map('intval',array_column(all('SELECT p.lesson_id FROM lesson_progress p JOIN lessons l ON l.id=p.lesson_id JOIN chapters ch ON ch.id=l.chapter_id WHERE p.user_id=? AND ch.course_id=?',[$u['id'],$id]),'lesson_id'));$default=null;foreach($ls as $l)if(!in_array((int)$l['id'],$done,true)){$default=$l;break;}$lid=(int)($_GET['lesson']??$e['last_lesson_id']??$default['id']??$ls[0]['id']??0);$lesson=lessonCourse($lid);if((int)$lesson['course_id']!==$id)reject('Bài học không thuộc khóa.',404);$p=progressFor((int)$u['id'],$id);?><main class="container wide"><div class="learning-top"><a href="<?=h(url('student'))?>">← Khóa học của tôi</a><span><?=h($c['title'])?></span></div><div class="learning-grid"><aside class="panel outline"><h3>Nội dung khóa học</h3><?php progressBar($p);foreach(all('SELECT * FROM chapters WHERE course_id=? ORDER BY position,id',[$id]) as $ch):?><h4><?=h($ch['title'])?></h4><?php foreach($ls as $l)if((int)$l['chapter_id']===(int)$ch['id']):echo formStart('last_lesson',['course_id'=>$id,'lesson_id'=>$l['id'],'return_page'=>'learn']);?><button class="lesson-link <?=$lid===(int)$l['id']?'active':''?>"><span><?=in_array((int)$l['id'],$done,true)?'✓':'○'?></span><?=h($l['title'])?></button></form><?php endif;endforeach?><a class="btn btn-outline-secondary w-100 mt-4" href="<?=h(url('quiz',['id'=>$id]))?>">Quiz cuối khóa <?=$p['percent']==100?'→':'· cần học đủ bài'?></a></aside><section class="panel lesson-panel"><p class="eyebrow">BÀI HỌC / <?=h($c['title'])?></p><?php lessonViewer($lesson);?><div class="lesson-actions"><?=formStart('complete',['lesson_id'=>$lid,'course_id'=>$id,'return_page'=>'learn'])?><button class="btn btn-primary" <?=in_array($lid,$done,true)?'disabled':''?>><?=in_array($lid,$done,true)?'✓ Đã hoàn thành bài':'Đánh dấu hoàn thành'?></button></form></div><p class="small muted mt-3">Tiến độ được ghi khi bạn đánh dấu, không chứng minh đã xem hết video.</p></section><?php renderAiPanel($lesson, $lid, $id); ?></div></main><?php }
function pageQuiz(int $id):void{$e=readyForQuiz($id);$qs=questionsFor($id);if(count($qs)<5)reject('Quiz chưa hợp lệ.',409);$_SESSION['quiz_uuid'][$id]??=uuid();?><main class="container quiz-container"><a href="<?=h(url('learn',['id'=>$id]))?>">← Về bài học</a><?php heading('LUYỆN TẬP CUỐI KHÓA','Kiểm tra điều bạn đã học','Đạt từ 70% để hoàn thành khóa; có thể làm lại, không giới hạn thời gian.');?><p class="quiz-note">Câu bỏ trống được tính sai. Refresh/rời trang có thể mất lựa chọn chưa nộp.</p><?=formStart('submit_quiz',['course_id'=>$id,'request_id'=>$_SESSION['quiz_uuid'][$id],'return_page'=>'quiz'])?><?php foreach($qs as $i=>$q):?><fieldset class="panel question"><legend>Câu <?=$i+1?>. <?=h($q['prompt'])?></legend><?php foreach($q['answers'] as $j=>$a):?><label class="answer-option"><input type="radio" name="answers[<?=$q['id']?>]" value="<?=$a['id']?>"><span class="answer-letter"><?=chr(65+$j)?></span><?=h($a['text'])?></label><?php endforeach?></fieldset><?php endforeach;echo confirmField();?><button class="btn btn-primary btn-lg">Nộp bài →</button></form><section class="panel mt-4"><h3>Lịch sử luyện tập</h3><?php $history=all('SELECT a.* FROM quiz_attempts a JOIN quizzes q ON q.id=a.quiz_id WHERE a.user_id=? AND q.course_id=? ORDER BY a.submitted_at DESC,a.id DESC',[$e['user_id'],$id]);foreach($history as $a):?><p><a href="<?=h(url('result',['id'=>$a['id']]))?>"><?=h($a['score_percent'])?>% · <?=$a['passed']?'Đạt':'Chưa đạt'?> · <?=h((new DateTimeImmutable($a['submitted_at'],new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Asia/Ho_Chi_Minh'))->format('d/m/Y H:i'))?></a></p><?php endforeach;if(!$history)echo '<p class="muted">Chưa có lần nộp.</p>';?></section></main><?php }
function pageResult(int $id):void{$u=requireUser('student');$a=one('SELECT a.*,q.course_id FROM quiz_attempts a JOIN quizzes q ON q.id=a.quiz_id WHERE a.id=? AND a.user_id=?',[$id,$u['id']]);if(!$a)reject('Không tìm thấy kết quả.',404);?><main class="container quiz-container"><section class="result-hero <?=$a['passed']?'passed':''?>"><p class="eyebrow">KẾT QUẢ LUYỆN TẬP</p><h1><?=$a['passed']?'Bạn đã hoàn thành thử thách!':'Thêm một lần luyện tập nhé.'?></h1><div class="score"><?=h($a['score_percent'])?><small>%</small></div><p>Đúng <?=$a['correct_count']?>/<?=$a['total_questions']?> câu · <?=$a['passed']?'Đạt':'Chưa đạt'?> · Ngưỡng 70%</p><div class="flex gap center"><a class="btn btn-primary" href="<?=h(url('quiz',['id'=>$a['course_id']]))?>">Làm lại quiz</a><a class="btn btn-outline-secondary" href="<?=h(url('student'))?>">Khóa học của tôi</a></div></section><h2 class="section-heading">Xem lại từng câu</h2><?php foreach(all('SELECT qa.*,q.prompt,q.explanation,q.position,selected.text selected_text,correct.text correct_text FROM quiz_answers qa JOIN questions q ON q.id=qa.question_id LEFT JOIN answers selected ON selected.id=qa.answer_id JOIN answers correct ON correct.question_id=q.id AND correct.is_correct=1 WHERE qa.attempt_id=? ORDER BY q.position,q.id',[$id]) as $answer):?><section class="panel review-question"><h3>Câu <?=$answer['position']?>. <?=h($answer['prompt'])?></h3><span class="badge <?=$answer['is_correct']?'text-bg-success':'text-bg-danger'?>"><?=$answer['is_correct']?'Đúng':($answer['answer_id']?'Chưa đúng':'Bỏ trống')?></span><p class="mt-3">Bạn chọn: <?=h($answer['selected_text']??'Chưa chọn')?></p><p>Đáp án đúng: <strong><?=h($answer['correct_text'])?></strong></p><p class="muted"><?=h($answer['explanation'])?></p></section><?php endforeach?></main><?php }
function pageProfile():void{$u=requireUser();?><main class="container"><?php heading('TÀI KHOẢN','Hồ sơ của bạn');?><section class="panel profile-panel"><h2><?=h($u['name'])?></h2><p><?=h($u['email'])?></p><span class="badge text-bg-light"><?=h($u['role'])?></span><p class="muted mt-4">Bản này chỉ hỗ trợ xem hồ sơ; không chỉnh sửa hoặc upload avatar.</p></section></main><?php }

function pagination(array $list):void{
 $params=$_GET;unset($params['p']);$page=(string)($params['page']??'home');unset($params['page']);
 echo '<nav class="pager" aria-label="Phân trang">';
 if($list['page']>1)echo '<a class="btn btn-outline-secondary" rel="prev" href="'.h(url($page,$params+['p'=>$list['page']-1])).'">Trước</a>';
 echo '<span>Trang '.$list['page'].' / '.$list['last'].' · '.$list['total'].' kết quả</span>';
 if($list['page']<$list['last'])echo '<a class="btn btn-outline-secondary" rel="next" href="'.h(url($page,$params+['p'=>$list['page']+1])).'">Sau</a>';
 echo '</nav>';
}
